"""Post-execution verification tools.

Closes the execute -> verify -> learn loop by:
1. Resolving ComfyUI output filenames to absolute paths
2. Validating outputs exist and have non-zero size
3. Optionally running vision analysis
4. Recording outcomes to memory for cross-session learning
"""

import hashlib
import json
import logging

import httpx

from ..config import COMFYUI_OUTPUT_DIR, COMFYUI_URL
from ._util import to_json, validate_path

log = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "get_output_path",
        "description": (
            "Resolve a ComfyUI output filename to its absolute path on disk. "
            "Use after execute_workflow or get_execution_status to find where "
            "ComfyUI saved the output file."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "filename": {
                    "type": "string",
                    "description": "Output filename from ComfyUI (e.g. 'ComfyUI_00001_.png').",
                },
                "subfolder": {
                    "type": "string",
                    "description": "Subfolder within output directory (default: empty).",
                },
            },
            "required": ["filename"],
        },
    },
    {
        "name": "verify_execution",
        "description": (
            "Post-execution verification: checks that outputs exist on disk, "
            "optionally analyzes image quality via Vision, and records the "
            "outcome to memory for learning. Call after execute_workflow or "
            "execute_with_progress to close the verify loop."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "prompt_id": {
                    "type": "string",
                    "description": "The prompt_id returned from execute_workflow.",
                },
                "analyze": {
                    "type": "boolean",
                    "description": (
                        "Run Claude Vision analysis on image outputs (costs tokens, "
                        "~120s). Default false -- set true for quality review."
                    ),
                },
                "session": {
                    "type": "string",
                    "description": "Session name for memory recording. Default 'default'.",
                },
                "render_time_s": {
                    "type": "number",
                    "description": "Total render time in seconds (from execute_with_progress).",
                },
                "goal_id": {
                    "type": "string",
                    "description": "Goal ID from planner, for linking outcome to a goal.",
                },
            },
            "required": ["prompt_id"],
        },
    },
]


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def _resolve_output_path(filename: str, subfolder: str = "") -> dict:
    """Resolve a ComfyUI output filename to absolute path + stats.

    Returns a dict (not JSON string) for internal use.
    """
    if not filename:
        return {
            "filename": filename,
            "subfolder": subfolder,
            "absolute_path": None,
            "exists": False,
            "size_bytes": 0,
            "error": "Empty filename",
        }

    output_dir = COMFYUI_OUTPUT_DIR
    if subfolder:
        abs_path = output_dir / subfolder / filename
    else:
        abs_path = output_dir / filename

    abs_path = abs_path.resolve()

    # Validate path is within safe directories
    path_err = validate_path(str(abs_path))
    if path_err:
        return {
            "filename": filename,
            "subfolder": subfolder,
            "absolute_path": str(abs_path),
            "exists": False,
            "size_bytes": 0,
            "error": path_err,
        }

    exists = abs_path.exists()
    size_bytes = abs_path.stat().st_size if exists else 0

    return {
        "filename": filename,
        "subfolder": subfolder,
        "absolute_path": str(abs_path),
        "exists": exists,
        "size_bytes": size_bytes,
        "error": None if exists else f"File not found: {abs_path}",
    }


def _extract_key_params(workflow: dict) -> dict:
    """Extract key generation parameters from a workflow dict.

    Scans for common node types: CheckpointLoaderSimple, KSampler,
    EmptyLatentImage. Returns a flat dict of key params.
    """
    params: dict = {}

    # He2025: sort for deterministic iteration
    for _nid, node in sorted(workflow.items()):
        if not isinstance(node, dict):
            continue
        class_type = node.get("class_type", "")
        inputs = node.get("inputs", {})

        if class_type == "CheckpointLoaderSimple":
            ckpt = inputs.get("ckpt_name")
            if isinstance(ckpt, str):
                params["model"] = ckpt

        elif class_type == "KSampler":
            for key in ("steps", "cfg", "sampler_name", "scheduler", "seed", "denoise"):
                val = inputs.get(key)
                if val is not None and not isinstance(val, list):
                    params[key] = val

        elif class_type == "EmptyLatentImage":
            w = inputs.get("width")
            h = inputs.get("height")
            if isinstance(w, (int, float)) and isinstance(h, (int, float)):
                params["resolution"] = f"{int(w)}x{int(h)}"

    return params


def _workflow_hash(workflow: dict) -> str:
    """Deterministic hash of workflow for fingerprinting."""
    raw = json.dumps(workflow, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(raw.encode("utf-8")).hexdigest()[:16]


def _verify_prompt(
    prompt_id: str,
    *,
    analyze: bool = False,
    session: str = "default",
    render_time_s: float | None = None,
    goal_id: str | None = None,
) -> dict:
    """Internal verification logic. Returns a dict (not JSON string).

    Called by verify_execution tool and by execute_with_progress auto_verify.
    """
    # 1. Fetch history for this prompt
    try:
        with httpx.Client() as client:
            resp = client.get(
                f"{COMFYUI_URL}/history/{prompt_id}",
                timeout=10.0,
            )

"""Vision module — gives the agent eyes.

Uses Claude Vision API to analyze generated images, compare outputs,
and suggest parameter improvements. Vision calls use a separate API call
to keep images out of the main conversation context window.

Also provides fast perceptual hash comparison via Pillow for instant
A/B regression testing without API calls.
"""

import base64
import json
import logging
from pathlib import Path

import anthropic

from ._protocol import brain_message, dispatch_brain_message
from ._sdk import BrainAgent

log = logging.getLogger(__name__)

try:
    from PIL import Image
    _HAS_PIL = True
except ImportError:
    _HAS_PIL = False

# Vision analysis uses a smaller max_tokens since responses are structured
_VISION_MAX_TOKENS = 4096
_VISION_TIMEOUT = 120  # seconds — max wait for Vision API response


class VisionAgent(BrainAgent):
    """Claude Vision-powered image analysis and comparison."""

    TOOLS: list[dict] = [
        {
            "name": "analyze_image",
            "description": (
                "Analyze a generated image using Claude Vision. Returns structured "
                "assessment: quality score (0-1), detected artifacts, composition notes, "
                "prompt adherence, and improvement suggestions. Use after execute_workflow "
                "to evaluate output quality."
            ),
            "input_schema": {
                "type": "object",
                "properties": {
                    "image_path": {
                        "type": "string",
                        "description": "Absolute path to the image file to analyze.",
                    },
                    "prompt_used": {
                        "type": "string",
                        "description": (
                            "The text prompt used to generate the image. "
                            "Helps assess prompt adherence."
                        ),
                    },
                    "workflow_context": {
                        "type": "string",
                        "description": (
                            "Brief description of the workflow (e.g., 'SDXL txt2img, "
                            "20 steps, DPM++ 2M Karras, CFG 7.0'). Optional."
                        ),
                    },
                },
                "required": ["image_path"],
            },
        },
        {
            "name": "compare_outputs",
            "description": (
                "Compare two images (same-seed A/B test). Returns what changed, "
                "whether it improved, and specific differences. Use after modifying "
                "a workflow to verify the change had the intended effect."
            ),
            "input_schema": {
                "type": "object",
                "properties": {
                    "image_a": {
                        "type": "string",
                        "description": "Path to the 'before' image.",
                    },
                    "image_b": {
                        "type": "string",
                        "description": "Path to the 'after' image.",
                    },
                    "change_description": {
                        "type": "string",
                        "description": (
                            "What was changed between A and B "
                            "(e.g., 'increased CFG from 7 to 12')."
                        ),
                    },
                },
                "required": ["image_a", "image_b"],
            },
        },
        {
            "name": "hash_compare_images",
            "description": (
                "Fast pixel-level comparison of two images using perceptual hashing. "
                "Returns similarity score, pixel difference percentage, and average "
                "color delta. Instant (no API call) — use as pre-check before "
                "compare_outputs to detect identical or near-identical images."
            ),
            "input_schema": {
                "type": "object",
                "properties": {
                    "image_a": {
                        "type": "string",
                        "description": "Path to the first image.",
                    },
                    "image_b": {
                        "type": "string",
                        "description": "Path to the second image.",
                    },
                },
                "required": ["image_a", "image_b"],
            },
        },
        {
            "name": "suggest_improvements",
            "description": (
                "Given an image and the workflow that produced it, suggest specific "
                "parameter tweaks to improve quality. Returns actionable suggestions "
                "with expected impact."
            ),
            "input_schema": {
                "type": "object",
                "properties": {
                    "image_path": {
                        "type": "string",
                        "description": "Path to the image to improve.",
                    },
                    "workflow_summary": {
                        "type": "string",
                        "description": (
                            "Summary of current workflow parameters: model, steps, "
                            "CFG, sampler, resolution, etc."
                        ),
                    },
                    "goal": {
                        "type": "string",
                        "description": (
                            "What the artist wants (e.g., 'more detail in faces', "
                            "'reduce noise in background', 'match reference style')."
                        ),
                    },

def _load_workflow_from_file(path_str: str) -> tuple[dict | None, str | None]:
    """Load API-format workflow from file. Returns (workflow, error)."""
    from pathlib import Path

    path = Path(path_str)
    if not path.exists():
        return None, f"File not found: {path_str}"

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        return None, f"Invalid JSON: {e}"

    # Extract API format
    if "nodes" in data and isinstance(data["nodes"], list):
        prompt_data = data.get("extra", {}).get("prompt")
        if prompt_data and isinstance(prompt_data, dict):
            nodes = {
                k: v for k, v in prompt_data.items()
                if isinstance(v, dict) and "class_type" in v
            }
            return nodes, None
        return None, "UI-only format -- can't execute without API data."

    nodes = {
        k: v for k, v in data.items()
        if isinstance(v, dict) and "class_type" in v
    }
    if not nodes:
        return None, "No nodes found in workflow."
    return nodes, None


def _queue_prompt(workflow: dict) -> tuple[str | None, str | None]:
    """Queue a workflow. Returns (prompt_id, error)."""
    payload = {
        "prompt": workflow,
        "client_id": _CLIENT_ID,
    }
    try:
        with httpx.Client() as client:
            resp = client.post(
                f"{COMFYUI_URL}/prompt",
                json=payload,
                timeout=30.0,
            )
            resp.raise_for_status()
            data = resp.json()
            prompt_id = data.get("prompt_id")
            if not prompt_id:
                return None, f"No prompt_id in response: {data}"
            return prompt_id, None
    except httpx.ConnectError:
        return None, f"ComfyUI not reachable at {COMFYUI_URL}. Is it running?"
    except httpx.HTTPStatusError as e:
        # ComfyUI returns errors in the response body
        try:
            err_data = e.response.json()
            # Format common errors nicely
            node_errors = err_data.get("node_errors", {})
            if node_errors:
                msgs = []
                # He2025: sort for deterministic error message order
                for nid, nerr in sorted(node_errors.items()):
                    class_type = nerr.get("class_type", "?")
                    for exc in nerr.get("errors", []):
                        msgs.append(f"Node [{nid}] {class_type}: {exc.get('message', str(exc))}")
                return None, "Validation errors:\n" + "\n".join(msgs)
            return None, err_data.get("error", str(err_data))
        except Exception:
            return None, f"HTTP {e.response.status_code}: {e.response.text[:300]}"
    except Exception as e:
        return None, str(e)


def _poll_completion(
    prompt_id: str,
    timeout: float,
    poll_interval: float = 1.0,
    progress: ProgressCallback | None = None,
) -> dict:
    """Poll /history until the prompt completes or times out."""
    progress = progress or ProgressReporter.noop()
    deadline = time.monotonic() + timeout
    start = time.monotonic()
    poll_count = 0

    while time.monotonic() < deadline:
        try:
            with httpx.Client() as client:
                resp = client.get(
                    f"{COMFYUI_URL}/history/{prompt_id}",
                    timeout=10.0,
                )
                resp.raise_for_status()
                history = resp.json()
        except Exception:
            time.sleep(poll_interval)
            continue

        if prompt_id in history:
            entry = history[prompt_id]
            status_info = entry.get("status", {})
            status_str = status_info.get("status_str", "unknown")
            completed = status_info.get("completed", False)

            if completed or status_str in ("success", "error"):
                # Extract outputs
                outputs = []
                # He2025: sort for deterministic output order
                for node_id, node_out in sorted(entry.get("outputs", {}).items()):
                    for img in node_out.get("images", []):
                        outputs.append({
                            "type": "image",
                            "filename": img.get("filename"),
                            "subfolder": img.get("subfolder", ""),
                        })
                    for vid in node_out.get("gifs", []):
                        outputs.append({
                            "type": "video",
                            "filename": vid.get("filename"),
                            "subfolder": vid.get("subfolder", ""),
                        })

                n = len(outputs)
                progress.report(
                    1.0, 1.0,
                    f"Complete — {n} output{'s' if n != 1 else ''}"
                )
                return {
                    "status": "complete" if status_str == "success" else status_str,
                    "prompt_id": prompt_id,
                    "outputs": outputs,
                }

        poll_count += 1
        elapsed = int(time.monotonic() - start)
        if poll_count % 3 == 0:
            progress.report(
                elapsed, timeout,
                f"Generating... ({elapsed}s elapsed)",
            )
        time.sleep(poll_interval)

    progress.report(timeout, timeout, "Timed out")
    return {
        "status": "timeout",
        "prompt_id": prompt_id,
        "message": f"Execution did not complete within {timeout}s. "

