"""Tool registry for the ComfyUI SUPER DUPER Agent.

Each tool module exports:
  TOOLS: list[dict]    -- Anthropic tool schemas
  handle(name, input)  -- Execute a tool call, return result string

Intelligence layers (53 tools) + Brain layer (27 tools) = 80 tools total.
Brain tools are lazily imported to avoid circular dependencies
(brain modules import _util from this package).
"""

import logging
import threading

from . import comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat, verify_execution, github_releases, pipeline, image_metadata, node_replacement

log = logging.getLogger(__name__)

_MODULES = (comfy_api, comfy_inspect, workflow_parse, workflow_patch, comfy_execute, comfy_discover, session_tools, workflow_templates, civitai_api, model_compat, verify_execution, github_releases, pipeline, image_metadata, node_replacement)

# Intelligence layer tool schemas
_LAYER_TOOLS: list[dict] = []
for _mod in _MODULES:
    _LAYER_TOOLS.extend(_mod.TOOLS)

# Map tool name -> handler module (intelligence layers)
_HANDLERS = {}
for _mod in _MODULES:
    for _tool in _mod.TOOLS:
        _HANDLERS[_tool["name"]] = _mod

# Brain tools are loaded lazily to break the circular import
_brain_loaded = False
_brain_lock = threading.Lock()
_BRAIN_TOOL_NAMES: set[str] = set()


def _ensure_brain():
    """Lazily load brain layer tools (thread-safe)."""
    global _brain_loaded, _BRAIN_TOOL_NAMES
    if _brain_loaded:
        return
    with _brain_lock:
        if _brain_loaded:  # double-check after acquiring lock
            return
        from ..brain import ALL_BRAIN_TOOLS
        _BRAIN_TOOL_NAMES.update(t["name"] for t in ALL_BRAIN_TOOLS)
        _brain_loaded = True


def _get_all_tools() -> list[dict]:
    """Get all tool schemas (intelligence + brain layers)."""
    _ensure_brain()
    from ..brain import ALL_BRAIN_TOOLS
    return _LAYER_TOOLS + list(ALL_BRAIN_TOOLS)


# Public API — ALL_TOOLS is a property-like accessor
class _ToolList(list):
    """Lazy tool list that includes brain tools on first access."""
    _initialized = False

    def _init_once(self):
        if not self._initialized:
            self._initialized = True
            self.extend(_LAYER_TOOLS)
            try:
                from ..brain import ALL_BRAIN_TOOLS
                self.extend(ALL_BRAIN_TOOLS)
            except ImportError:
                log.warning("Brain layer not available")

    def __iter__(self):
        self._init_once()
        return super().__iter__()

    def __len__(self):
        self._init_once()
        return super().__len__()

    def __getitem__(self, idx):
        self._init_once()
        return super().__getitem__(idx)


ALL_TOOLS = _ToolList()


def handle(
    name: str,
    tool_input: dict,
    *,
    session_id: str | None = None,
    progress: "ProgressCallback | None" = None,
) -> str:
    """Dispatch a tool call to the right handler.

    Args:
        name: Tool name to dispatch.
        tool_input: Tool arguments dict.
        session_id: Optional session ID for workflow state isolation.
                    Currently unused (default session), but enables future
                    multi-session MCP usage.
        progress: Optional progress reporter for long-running tools.
                  Passed through to handlers that support it.
    """
    from ..progress import ProgressCallback  # noqa: F811 (type only)

    # Check brain tools (lazy loaded)
    _ensure_brain()
    if name in _BRAIN_TOOL_NAMES:
        from ..brain import handle as handle_brain
        try:
            return handle_brain(name, tool_input)
        except Exception as e:
            log.error("Unhandled error in brain tool %s", name, exc_info=True)
            from ._util import to_json
            return to_json(
                {"error": f"Internal error in {name}: {type(e).__name__}: {e}"}
            )

    # Intelligence layer tools
    mod = _HANDLERS.get(name)
    if mod is None:
        log.warning("Unknown tool called: %s", name)
        return f"Unknown tool: {name}"
    try:
        # Forward progress to modules that accept it
        if mod is comfy_execute:
            return mod.handle(name, tool_input, progress=progress)
        return mod.handle(name, tool_input)
    except Exception as e:
        log.error("Unhandled error in tool %s", name, exc_info=True)
        from ._util import to_json
        return to_json({"error": f"Internal error in {name}: {type(e).__name__}: {e}"})

"""Workflow patching tools.

Apply RFC6902 JSON patches to ComfyUI workflows with full undo support.
The agent reasons about what changes to make, then calls these tools
with concrete patch operations.

State is module-level: load a workflow once, patch it multiple times,
undo as needed, then save or execute.
"""

import copy
import json
from pathlib import Path

import jsonpatch

from ._util import to_json

# ---------------------------------------------------------------------------
# Module-level state (one active workflow at a time)
# ---------------------------------------------------------------------------
# WorkflowSession is dict-like: _state["key"] and _state.get("key") work.
# The lock is per-session, so the existing `with _state_lock:` pattern
# continues to work for the default session.

from ..workflow_session import get_session

_state = get_session("default")
_state_lock = _state._lock


def _ensure_loaded() -> str | None:
    """Return error message if no workflow is loaded, else None."""
    if _state["current_workflow"] is None:
        return "No workflow loaded. Use apply_workflow_patch with a file path first."
    return None


def _load_workflow(path_str: str) -> str | None:
    """Load a workflow into state. Returns error or None."""
    from ._util import validate_path
    path_err = validate_path(path_str, must_exist=True)
    if path_err:
        return path_err
    path = Path(path_str)

    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        return f"Invalid JSON: {e}"

    # Extract API format
    if "nodes" in data and isinstance(data["nodes"], list):
        prompt_data = data.get("extra", {}).get("prompt")
        if prompt_data and isinstance(prompt_data, dict):
            api_nodes = {
                k: v for k, v in prompt_data.items()
                if isinstance(v, dict) and "class_type" in v
            }
            _state["format"] = "ui_with_api"
        else:
            return (
                "UI-only workflow format -- can't patch without API data. "
                "Re-export using 'Save (API Format)' in ComfyUI."
            )
    else:
        api_nodes = {
            k: v for k, v in data.items()
            if isinstance(v, dict) and "class_type" in v
        }
        _state["format"] = "api"

    if not api_nodes:
        return "No nodes found in workflow."

    _state["loaded_path"] = path_str
    _state["base_workflow"] = copy.deepcopy(api_nodes)
    _state["current_workflow"] = copy.deepcopy(api_nodes)
    _state["history"] = []
    return None


# ---------------------------------------------------------------------------
# Tool schemas
# ---------------------------------------------------------------------------

TOOLS: list[dict] = [
    {
        "name": "apply_workflow_patch",
        "description": (
            "Apply RFC6902 JSON patches to a workflow. If no workflow is "
            "loaded yet, provide the file path to load it first. "
            "Patches use the format: "
            '[{"op": "replace", "path": "/node_id/inputs/field", "value": new_value}]. '
            "Returns the changes made and the current state of affected fields. "
            "Supports undo via undo_workflow_patch."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "path": {
                    "type": "string",
                    "description": (
                        "Path to workflow JSON file. Required on first call, "
                        "optional after (reuses loaded workflow)."
                    ),
                },
                "patches": {
                    "type": "array",
                    "description": (
                        "RFC6902 patch operations. Each has 'op' (usually 'replace'), "
                        "'path' (e.g. '/5/inputs/text'), and 'value'."
                    ),
                    "items": {
                        "type": "object",
                        "properties": {
                            "op": {"type": "string"},
                            "path": {"type": "string"},
                            "value": {},
                        },
                        "required": ["op", "path", "value"],
                    },
                },
            },
            "required": ["patches"],
        },
    },
    {
        "name": "preview_workflow_patch",
        "description": (
            "Preview what a patch would change WITHOUT applying it. "
            "Shows before/after values for each affected field."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "patches": {
                    "type": "array",
                    "description": "RFC6902 patch operations to preview.",
                    "items": {
                        "type": "object",
                        "properties": {
                            "op": {"type": "string"},
                            "path": {"type": "string"},
                            "value": {},
                        },
                        "required": ["op", "path", "value"],
                    },
                },
            },
            "required": ["patches"],
        },
    },
    {
        "name": "undo_workflow_patch",
        "description": (
            "Undo the last patch operation. Can be called multiple times "
            "to step back through history."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "get_workflow_diff",
        "description": (
            "Show all changes from the original workflow as a JSON patch diff. "
            "Useful for reviewing everything that's been modified."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    {
        "name": "save_workflow",
        "description": (
            "Save the current (patched) workflow to a file. "
            "If no output path is given, overwrites the original."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "output_path": {
                    "type": "string",
                    "description": (
                        "Path to save the workflow. If omitted, overwrites the original file."
                    ),
                },
            },
            "required": [],
        },
    },
    {
        "name": "reset_workflow",
        "description": (
            "Reset the workflow back to its original state, discarding all patches."
        ),
        "input_schema": {
            "type": "object",
            "properties": {},
            "required": [],
        },
    },
    # --- Semantic composition tools ---
    {
        "name": "add_node",
        "description": (
            "Add a new node to the loaded workflow. Assigns a unique node ID "
            "and sets up the node with the given class_type and optional input values. "
            "Returns the assigned node_id so you can connect it to other nodes. "
            "A workflow must be loaded first (via apply_workflow_patch or load from template)."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "class_type": {
                    "type": "string",
                    "description": "Node class_type (e.g. 'KSampler', 'CLIPTextEncode', 'CheckpointLoaderSimple').",
                },
                "inputs": {
                    "type": "object",
                    "description": (
                        "Optional initial input values. Keys are input names, "
                        "values are literals (int, float, str). Connections should "
                        "be set separately with connect_nodes."
                    ),
                },
            },
            "required": ["class_type"],
        },
    },
    {
        "name": "connect_nodes",
        "description": (
            "Connect one node's output to another node's input. "
            "This sets the connection in the workflow graph. "
            "Example: connect KSampler output 0 to VAEDecode input 'samples'."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "from_node": {
                    "type": "string",
                    "description": "Source node ID (the node producing the output).",
                },
                "from_output": {
                    "type": "integer",
                    "description": "Output index on the source node (usually 0).",
                },
                "to_node": {
                    "type": "string",
                    "description": "Target node ID (the node receiving the input).",
                },
                "to_input": {
                    "type": "string",
                    "description": "Input name on the target node (e.g. 'model', 'samples', 'clip').",
                },
            },
            "required": ["from_node", "from_output", "to_node", "to_input"],
        },
    },
    {
        "name": "set_input",
        "description": (
            "Set a literal input value on a node. For connections between nodes, "
            "use connect_nodes instead. This is for values like seed, steps, "
            "cfg, sampler_name, prompt text, model filenames, etc."
        ),
        "input_schema": {
            "type": "object",
            "properties": {
                "node_id": {
                    "type": "string",
                    "description": "Target node ID.",
                },
                "input_name": {
                    "type": "string",
                    "description": "Input field name (e.g. 'seed', 'steps', 'text', 'ckpt_name').",
                },
                "value": {
                    "description": "The value to set (string, int, float, bool).",
                },
            },
            "required": ["node_id", "input_name", "value"],
        },
    },
]

# ---------------------------------------------------------------------------
# Handlers
# ---------------------------------------------------------------------------

def _get_value_at_path(workflow: dict, path: str):
    """Navigate a JSON path and return the value, or None."""
    parts = path.strip("/").split("/")
    current = workflow
    for part in parts:
        if isinstance(current, dict):
            current = current.get(part)
        elif isinstance(current, list) and part.isdigit():
            idx = int(part)
            current = current[idx] if idx < len(current) else None
        else:
            return None
        if current is None:
            return None
    return current


def _handle_apply_patch(tool_input: dict) -> str:
    path_str = tool_input.get("path")
    patches = tool_input["patches"]

    # Load workflow if path provided or not loaded yet
    if path_str:
        err = _load_workflow(path_str)
        if err:
            return to_json({"error": err})
    elif _state["current_workflow"] is None:
        return to_json({
            "error": "No workflow loaded. Provide a 'path' to load one first."
        })

    # Record before values for the diff report
    before_values = {}
    for patch in patches:
        p = patch.get("path", "")
        before_values[p] = _get_value_at_path(_state["current_workflow"], p)

    # Save current state for undo
    _state["history"].append(copy.deepcopy(_state["current_workflow"]))

    # Apply patches
    try:
        jp = jsonpatch.JsonPatch(patches)
        _state["current_workflow"] = jp.apply(_state["current_workflow"])
    except Exception as e:
        # Rollback on failure
        _state["current_workflow"] = _state["history"].pop()
        return to_json({"error": f"Patch failed: {e}"})

    # Build change report
    changes = []
    for patch in patches:
        p = patch.get("path", "")
        changes.append({
            "path": p,
            "op": patch.get("op"),
            "before": before_values.get(p),
            "after": patch.get("value"),
        })

    return to_json({
        "applied": len(patches),
        "changes": changes,
        "undo_available": True,
        "total_changes_from_base": len(
            jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch
        ),
    })


def _handle_preview_patch(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    patches = tool_input["patches"]

    # Preview without modifying state
    preview = []
    try:
        jp = jsonpatch.JsonPatch(patches)
        jp.apply(copy.deepcopy(_state["current_workflow"]))
    except Exception as e:
        return to_json({"error": f"Patch would fail: {e}"})

    for patch in patches:
        p = patch.get("path", "")
        preview.append({
            "path": p,
            "op": patch.get("op"),
            "current_value": _get_value_at_path(_state["current_workflow"], p),
            "new_value": patch.get("value"),
        })

    return to_json({"preview": preview, "would_succeed": True})


def _handle_undo() -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    if not _state["history"]:
        return to_json({"error": "Nothing to undo."})

    _state["current_workflow"] = _state["history"].pop()

    remaining = len(
        jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch
    )
    return to_json({
        "undone": True,
        "remaining_changes_from_base": remaining,
        "undo_steps_remaining": len(_state["history"]),
    })


def _handle_get_diff() -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    diff = jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch

    if not diff:
        return to_json({"changes": 0, "message": "No changes from original."})

    return to_json({
        "changes": len(diff),
        "diff": diff,
        "loaded_from": _state["loaded_path"],
    })


def _handle_save(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    output_path = tool_input.get("output_path") or _state["loaded_path"]
    if not output_path:
        return to_json({"error": "No output path specified."})

    from ._util import validate_path
    path_err = validate_path(output_path)
    if path_err:
        return to_json({"error": path_err})

    try:
        Path(output_path).write_text(
            to_json(_state["current_workflow"], indent=2),
            encoding="utf-8",
        )
    except Exception as e:
        return to_json({"error": f"Failed to save: {e}"})

    changes = len(
        jsonpatch.make_patch(_state["base_workflow"], _state["current_workflow"]).patch
    )
    return to_json({
        "saved": output_path,
        "changes_from_base": changes,
    })


def _handle_reset() -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    _state["current_workflow"] = copy.deepcopy(_state["base_workflow"])
    _state["history"] = []

    return to_json({
        "reset": True,
        "loaded_from": _state["loaded_path"],
    })


# ---------------------------------------------------------------------------
# Semantic composition handlers
# ---------------------------------------------------------------------------

def _next_node_id() -> str:
    """Find the next available numeric node ID."""
    workflow = _state["current_workflow"]
    if not workflow:
        return "1"
    existing = set()
    for key in workflow:
        try:
            existing.add(int(key))
        except ValueError:
            pass
    next_id = max(existing, default=0) + 1
    return str(next_id)


def _handle_add_node(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    class_type = tool_input["class_type"]
    inputs = tool_input.get("inputs", {})

    # Save state for undo
    _state["history"].append(copy.deepcopy(_state["current_workflow"]))

    node_id = _next_node_id()
    _state["current_workflow"][node_id] = {
        "class_type": class_type,
        "inputs": inputs,
    }

    return to_json({
        "added": True,
        "node_id": node_id,
        "class_type": class_type,
        "inputs": inputs,
        "total_nodes": len(_state["current_workflow"]),
    })


def _handle_connect_nodes(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    from_node = tool_input["from_node"]
    from_output = tool_input["from_output"]
    to_node = tool_input["to_node"]
    to_input = tool_input["to_input"]

    workflow = _state["current_workflow"]

    # Validate nodes exist
    if from_node not in workflow:
        return to_json({"error": f"Source node '{from_node}' not found in workflow."})
    if to_node not in workflow:
        return to_json({"error": f"Target node '{to_node}' not found in workflow."})

    # Save state for undo
    _state["history"].append(copy.deepcopy(workflow))

    # Set connection (ComfyUI format: [source_node_id_str, output_index_int])
    old_value = workflow[to_node].get("inputs", {}).get(to_input)
    workflow[to_node].setdefault("inputs", {})[to_input] = [from_node, from_output]

    from_class = workflow[from_node].get("class_type", "?")
    to_class = workflow[to_node].get("class_type", "?")

    return to_json({
        "connected": True,
        "from": f"{from_class} [{from_node}] output {from_output}",
        "to": f"{to_class} [{to_node}].{to_input}",
        "previous_value": old_value,
    })


def _handle_set_input(tool_input: dict) -> str:
    err = _ensure_loaded()
    if err:
        return to_json({"error": err})

    node_id = tool_input["node_id"]
    input_name = tool_input["input_name"]
    value = tool_input["value"]

    workflow = _state["current_workflow"]

    if node_id not in workflow:
        return to_json({"error": f"Node '{node_id}' not found in workflow."})

    # Save state for undo
    _state["history"].append(copy.deepcopy(workflow))

    old_value = workflow[node_id].get("inputs", {}).get(input_name)
    workflow[node_id].setdefault("inputs", {})[input_name] = value

    class_type = workflow[node_id].get("class_type", "?")

    return to_json({
        "set": True,
        "node": f"{class_type} [{node_id}]",
        "input": input_name,
        "old_value": old_value,
        "new_value": value,
    })


# ---------------------------------------------------------------------------
# Dispatch
# ---------------------------------------------------------------------------

def handle(name: str, tool_input: dict) -> str:
    """Execute a workflow_patch tool call."""
    with _state_lock:
        try:
            if name == "apply_workflow_patch":
                return _handle_apply_patch(tool_input)
            elif name == "preview_workflow_patch":
                return _handle_preview_patch(tool_input)
            elif name == "undo_workflow_patch":
                return _handle_undo()
            elif name == "get_workflow_diff":
                return _handle_get_diff()
            elif name == "save_workflow":
                return _handle_save(tool_input)
            elif name == "reset_workflow":
                return _handle_reset()
            elif name == "add_node":
                return _handle_add_node(tool_input)
            elif name == "connect_nodes":
                return _handle_connect_nodes(tool_input)
            elif name == "set_input":
                return _handle_set_input(tool_input)
            else:
                return to_json({"error": f"Unknown tool: {name}"})
        except Exception as e:
            return to_json({"error": str(e)})


def load_workflow_from_data(data: dict, source: str = "<sidebar>") -> str | None:
    """Load a workflow from raw dict data (no filesystem I/O).

    Called by the sidebar backend to inject the live ComfyUI graph.
    Returns None on success, error string on failure.
    """
    from .workflow_parse import _extract_api_format

    nodes, fmt = _extract_api_format(data)

    if fmt == "ui_only":
        return (
            "UI-only workflow format -- can't patch without API data. "
            "Re-export using 'Save (API Format)' in ComfyUI."
        )

    if not nodes:
        return "No nodes found in workflow data."

    with _state_lock:
        _state["loaded_path"] = source
        _state["format"] = fmt
        _state["base_workflow"] = copy.deepcopy(nodes)
        _state["current_workflow"] = copy.deepcopy(nodes)
        _state["history"] = []

    return None


def get_current_workflow() -> dict | None:
    """Get the current workflow dict (used by comfy_execute)."""
    return _state["current_workflow"]

"""Command-line interface for the ComfyUI Agent."""

import atexit
import json
import logging
import signal
import threading

import typer
from rich.console import Console
from rich.panel import Panel
from rich.table import Table

from .config import AGENT_MODEL, COMFYUI_URL, COMFYUI_DATABASE, ANTHROPIC_API_KEY, LOG_DIR
from .logging_config import setup_logging
from .tools import comfy_inspect, comfy_discover, session_tools

log = logging.getLogger(__name__)

app = typer.Typer(
    help="ComfyUI Agent — AI co-pilot for ComfyUI workflows",
    no_args_is_help=True,
)
console = Console()


@app.command()
def run(
    session: str = typer.Option(
        None, "--session", "-s",
        help="Named session for memory persistence",
    ),
    verbose: bool = typer.Option(
        False, "--verbose", "-v",
        help="Show debug logging (API timing, tool execution, context management)",
    ),
):
    """Start an interactive agent session."""
    # Configure logging
    setup_logging(
        level=logging.DEBUG if verbose else logging.WARNING,
        log_file=LOG_DIR / "agent.log",
    )
    # Validate API key
    if not ANTHROPIC_API_KEY:
        console.print(
            "[red]ANTHROPIC_API_KEY not set.[/red]\n"
            "Setup steps:\n"
            "  1. Copy .env.example to .env\n"
            "  2. Get a key from https://console.anthropic.com/\n"
            "  3. Add: ANTHROPIC_API_KEY=sk-ant-...\n"
        )
        raise typer.Exit(1)

    # Show header
    console.print(Panel.fit(
        f"[bold blue]ComfyUI Agent[/bold blue]\n"
        f"Model: {AGENT_MODEL}\n"
        f"ComfyUI: {COMFYUI_URL}\n"
        f"Database: {COMFYUI_DATABASE}",
        title="ComfyUI Agent v0.4",
    ))

    # Load session context for system prompt injection
    session_context = None
    if session:
        console.print(f"[dim]Session: {session}[/dim]")
        # Restore session state
        load_result = json.loads(session_tools.handle("load_session", {"name": session}))
        if "error" not in load_result:
            console.print(f"[dim]Restored session from {load_result.get('saved_at', '?')}[/dim]")
            if load_result.get("workflow_restored"):
                console.print(f"[dim]Workflow loaded: {load_result.get('workflow_path')}[/dim]")
            if load_result.get("notes_count", 0) > 0:
                console.print(f"[dim]{load_result['notes_count']} note(s) from previous session[/dim]")
            # Build session context for system prompt
            session_context = {
                "name": session,
                "notes": load_result.get("notes", []),
                "workflow": {
                    "loaded_path": load_result.get("workflow_path"),
                    "format": load_result.get("workflow_format"),
                    "history_depth": 0,
                },
            }

    console.print("[dim]Type your question or command. 'quit' to exit.[/dim]\n")

    # Import here to avoid loading anthropic at CLI startup
    from .main import create_client, run_interactive, request_shutdown

    client = create_client()

    # Graceful shutdown: save session on SIGTERM or atexit
    _shutdown_done = threading.Event()

    def _save_and_exit(signum=None, frame=None):
        if _shutdown_done.is_set():
            return
        _shutdown_done.set()
        request_shutdown()
        if session:
            try:
                save_result = json.loads(
                    session_tools.handle("save_session", {"name": session})
                )
                if "saved" in save_result:
                    console.print(f"\n[dim]Session '{session}' saved.[/dim]")
            except Exception as e:
                log.warning(
                    "Failed to save session '%s' on exit: %s", session, e
                )

    signal.signal(signal.SIGTERM, _save_and_exit)
    atexit.register(
        lambda: _save_and_exit() if session and not _shutdown_done.is_set() else None
    )

    # Streaming callbacks
    _streamed_any = False

    def on_text_delta(text: str):
        nonlocal _streamed_any
        _streamed_any = True
        print(text, end="", flush=True)

    def on_tool_call(name: str, inp: dict):
        nonlocal _streamed_any
        if _streamed_any:
            print()  # Newline after streamed text
            _streamed_any = False
        inp_summary = json.dumps(inp, default=str, sort_keys=True)
        if len(inp_summary) > 80:
            inp_summary = inp_summary[:77] + "..."
        console.print(f"  [dim]-> {name}({inp_summary})[/dim]")

    def on_stream_end():
        nonlocal _streamed_any
        if _streamed_any:
            print()  # Final newline after streamed text
            _streamed_any = False

    def on_user_input() -> str | None:
        try:
            return console.input("[bold cyan]> [/bold cyan]")
        except (KeyboardInterrupt, EOFError):
            console.print()
            return None

    run_interactive(
        client,
        session_context=session_context,
        on_text_delta=on_text_delta,
        on_tool_call=on_tool_call,
        on_stream_end=on_stream_end,
        on_user_input=on_user_input,
    )

    # Save session on normal exit (atexit handles abnormal exit)
    _save_and_exit()

    console.print("\n[dim]Goodbye![/dim]")


