        try:
            data = json.loads(path.read_text(encoding="utf-8"))
            sessions.append({
                "name": data.get("name", path.stem),
                "saved_at": data.get("saved_at", ""),
                "notes_count": len(data.get("notes", [])),
                "has_workflow": data.get("workflow", {}).get("loaded_path") is not None,
                "file": str(path),
            })
